#![cfg(mobile)]
//! The mobile app's native side, as a Tauri plugin (design D.4, generator model G-a): `gen/android` is regenerated by the
//! Tauri CLI, never edited by hand, so what the Android app needs beyond the template lives in the Android library under
//! `android/`, whose manifest, resources and code Gradle merges into the app's.
//!
//! - **The system's call** ([`call_service`]): the call as a phone call of the system's own when the app asks for it (off by
//!   default: the app's own call runs only Android's foreground service), which the lock screen, the
//!   in-call screens and a Bluetooth or car kit show. On Android a foreground service keeps the process alive while the
//!   screen is off or another app is in front, and holds a self-managed Telecom call (Core-Telecom); on iOS it is a CallKit
//!   call. The app starts it while it is visible and ends it when the call ends.
//!
//!   Its iOS body is Rust (objc2's CallKit bindings), like the rest of the app's iOS code: the plugin has no Swift.
//! - **The call's surfaces** ([`call_surface`]): what the app's own Live Activity (iOS) and call notification (Android)
//!   draw, carried in the call's details, with the creatures' stills kept by id where those read them, and what the
//!   person asks for on them, reported as the call's events. The Live Activity is started, updated and ended with the
//!   app's own call; its views and buttons are Swift (mobile/tauri/apple), which the Rust side reaches by name.
//! - **The screen** ([`keep_screen_on`], [`screen_locked`]): kept on while a model download runs, since the system suspends
//!   the app, and the download, soon after the screen turns off; and whether it is locked, for the page's "only with the
//!   screen off" thinking sound, which the app's own player applies itself with the screen locked ([`When`]).
mod call_service;
mod call_surface;
mod cue;
mod platform;
mod screen;

use tauri::{plugin::TauriPlugin, Runtime};

pub use call_service::{
    call_activates_audio, call_replaces_media_controls, refresh_call_service, request_call_focus,
    start_call_service, stop_call_service, update_call_service, CallDetails, CallEvent, CallEvents,
    CallServiceError, FocusState, StopReason,
};
pub use call_surface::{
    clear_stills, forget_stills, os_log, save_still, stills_dir, CallSurface, Other, Phase,
    SpokenPage, Still, StillError, SurfaceAction, SurfaceWords, STILLS_CAP, STILL_ID_LIMIT,
    STILL_LIMIT, STILL_MAX_PX, URL_SCHEME,
};
pub use cue::{
    cue_available, cue_current, cue_ticket, end_cues, gain_db, interval_scale, prepare_cue,
    start_cue, stop_cue, Cue, Prepared, When,
};
pub use screen::{keep_screen_on, screen_locked, ScreenError};

pub fn init<R: Runtime>() -> TauriPlugin<R> {
    tauri::plugin::Builder::new("mobile")
        .setup(|app, api| {
            // A surface an earlier run left (the app was ended during a call) shows no call of this one.
            call_surface::end_surface();
            // The cue the page starts for "only with the screen off" plays from the lock to the unlock (`cue::When`).
            cue::follow_the_lock(app);
            platform::call_service::register(api)
        })
        .build()
}

#[cfg(test)]
mod tests {
    const MANIFEST: &str = include_str!("../android/src/main/AndroidManifest.xml");
    const BACKUP_RULES: &str = include_str!("../android/src/main/res/xml/backup_rules.xml");
    const DATA_EXTRACTION_RULES: &str =
        include_str!("../android/src/main/res/xml/data_extraction_rules.xml");

    /// What stays out of a backup: the folder of the pairings record (`pairings/` in `mobile/tauri/src/pairings.rs`; the temporary
    /// file of a write is in it too, and no rule could name that) and the SharedPreferences file of the provider keys
    /// (`keyring-` and the store's name, `shared/core/src/platform/credentials/android.rs`).
    const EXCLUDED: [&str; 2] = [
        r#"<exclude domain="file" path="pairings/" />"#,
        r#"<exclude domain="sharedpref" path="keyring-sidevoice-providers.xml" />"#,
    ];

    /// The text between `<tag>` and `</tag>`.
    fn inside<'a>(xml: &'a str, tag: &str) -> &'a str {
        let (open, close) = (format!("<{tag}>"), format!("</{tag}>"));
        let start = xml.find(&open).unwrap_or_else(|| panic!("no <{tag}>")) + open.len();
        &xml[start
            ..start
                + xml[start..]
                    .find(&close)
                    .unwrap_or_else(|| panic!("no </{tag}>"))]
    }

    #[test]
    fn the_manifest_points_the_app_to_both_rule_files() {
        assert!(MANIFEST.contains(r#"android:dataExtractionRules="@xml/data_extraction_rules""#));
        assert!(MANIFEST.contains(r#"android:fullBackupContent="@xml/backup_rules""#));
    }

    #[test]
    fn android_12_and_newer_exclude_both_from_a_backup_and_from_a_transfer() {
        for channel in ["cloud-backup", "device-transfer"] {
            let rules = inside(DATA_EXTRACTION_RULES, channel);
            for excluded in EXCLUDED {
                assert!(rules.contains(excluded), "{channel}: {excluded}");
            }
        }
    }

    #[test]
    fn android_11_and_older_exclude_both_from_a_backup() {
        let rules = inside(BACKUP_RULES, "full-backup-content");
        for excluded in EXCLUDED {
            assert!(rules.contains(excluded), "{excluded}");
        }
    }
}
